//#region src/build/resolveLinkedPageChunkFiles.ts
/**
* Resolve the chunk output file names of pages linked from the current page.
*/
const resolveLinkedPageChunkFiles = ({ base, page, pageChunkFilesMap }) => {
	const linkedPageChunkFiles = /* @__PURE__ */ new Set();
	for (const link of page.links) {
		const routePath = resolveLinkRoutePath({
			base,
			current: page.path,
			link
		});
		if (routePath) {
			const targetChunks = pageChunkFilesMap.get(routePath);
			if (targetChunks) for (const file of targetChunks) linkedPageChunkFiles.add(file);
		}
	}
	return linkedPageChunkFiles;
};
